#include <stdio.h>
#include <stdlib.h>

int bfs_farthest(int n, int *head, int *to, int *next, int start,
                 int *dist, int *parent, int *queue) {
    for (int i = 1; i <= n; ++i) dist[i] = -1;

    int front = 0, back = 0;
    queue[back++] = start;
    dist[start] = 0;
    parent[start] = 0;

    int far = start;
    while (front < back) {
        int u = queue[front++];
        if (dist[u] > dist[far]) far = u;

        for (int e = head[u]; e != -1; e = next[e]) {
            int v = to[e];
            if (dist[v] == -1) {
                dist[v] = dist[u] + 1;
                parent[v] = u;
                queue[back++] = v;
            }
        }
    }

    return far;
}

int get_center(int n) {
    int *head = (int *)malloc((n + 1) * sizeof(int));
    int *to = (int *)malloc((2 * (n - 1) + 2) * sizeof(int));
    int *next = (int *)malloc((2 * (n - 1) + 2) * sizeof(int));

    for (int i = 1; i <= n; ++i) head[i] = -1;

    int idx = 0;
    for (int i = 0; i < n - 1; ++i) {
        int a, b;
        scanf("%d %d", &a, &b);

        to[idx] = b;
        next[idx] = head[a];
        head[a] = idx++;

        to[idx] = a;
        next[idx] = head[b];
        head[b] = idx++;
    }

    int *dist = (int *)malloc((n + 1) * sizeof(int));
    int *parent = (int *)malloc((n + 1) * sizeof(int));
    int *queue = (int *)malloc((n + 1) * sizeof(int));

    int s = bfs_farthest(n, head, to, next, 1, dist, parent, queue);
    int t = bfs_farthest(n, head, to, next, s, dist, parent, queue);

    int diameter_edges = dist[t];
    int cur = t;

    for (int i = 0; i < diameter_edges / 2; ++i) {
        cur = parent[cur];
    }

    free(head);
    free(to);
    free(next);
    free(dist);
    free(parent);
    free(queue);

    return cur;
}

int main(void) {
    int n, m;
    if (scanf("%d %d", &n, &m) != 2) return 0;

    int center_circle = get_center(n);
    int center_square = get_center(m);

    printf("%d %d\n", center_circle, center_square);

    return 0;
}
